/*
# Knowledge Checks (15+ questions per ACORD form)

Generated by supabase/knowledge-checks/build.mjs from supabase/knowledge-checks/questions.mjs — edit the questions there.

Flow per module:  training video (95% watched, server-verified)  ->  Knowledge Check (pass 80%)  ->  PDF assessment.

- Questions and correct answers are staff-only; students receive questions WITHOUT answers via get_knowledge_check().
- submit_knowledge_check() grades on the server. Failed attempts only reveal WHICH questions were wrong;
  the correct answers and explanations are shown once the student passes.
- start_assessment() now refuses to start until the module's Knowledge Check is passed.
*/

-- ============================================================ tables
CREATE TABLE IF NOT EXISTS public.knowledge_check_questions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  module_id text NOT NULL REFERENCES public.acord_modules(id),
  question_key text NOT NULL,
  sort_order integer NOT NULL DEFAULT 0,
  prompt text NOT NULL,
  options jsonb NOT NULL CHECK (jsonb_typeof(options) = 'array' AND jsonb_array_length(options) BETWEEN 2 AND 6),
  correct_index integer NOT NULL CHECK (correct_index >= 0),
  explanation text NOT NULL DEFAULT '',
  is_active boolean NOT NULL DEFAULT true,
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (module_id, question_key),
  CHECK (correct_index < jsonb_array_length(options))
);
ALTER TABLE public.knowledge_check_questions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.knowledge_check_questions FROM anon;
DROP POLICY IF EXISTS "kc_questions_staff_all" ON public.knowledge_check_questions;
CREATE POLICY "kc_questions_staff_all" ON public.knowledge_check_questions FOR ALL TO authenticated
  USING (public.is_staff()) WITH CHECK (public.is_staff());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.knowledge_check_questions TO authenticated;

CREATE TABLE IF NOT EXISTS public.knowledge_check_attempts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  module_id text NOT NULL REFERENCES public.acord_modules(id),
  score integer NOT NULL,
  correct integer NOT NULL,
  total integer NOT NULL,
  passed boolean NOT NULL,
  answers jsonb NOT NULL DEFAULT '{}'::jsonb,
  results jsonb NOT NULL DEFAULT '[]'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_kc_attempts_user_module ON public.knowledge_check_attempts(user_id, module_id, created_at DESC);
ALTER TABLE public.knowledge_check_attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.knowledge_check_attempts FROM anon;
DROP POLICY IF EXISTS "kc_attempts_select" ON public.knowledge_check_attempts;
CREATE POLICY "kc_attempts_select" ON public.knowledge_check_attempts FOR SELECT TO authenticated
  USING (user_id = auth.uid() OR public.is_staff());
DROP POLICY IF EXISTS "kc_attempts_staff_delete" ON public.knowledge_check_attempts;
CREATE POLICY "kc_attempts_staff_delete" ON public.knowledge_check_attempts FOR DELETE TO authenticated
  USING (public.is_staff());
GRANT SELECT, DELETE ON public.knowledge_check_attempts TO authenticated;
-- Inserts only happen through submit_knowledge_check() (SECURITY DEFINER).

-- ============================================================ question bank
INSERT INTO public.knowledge_check_questions (module_id, question_key, sort_order, prompt, options, correct_index, explanation)
VALUES
  ('125', 'purpose', 1, 'What is the main role of the ACORD 125?', '["It is a certificate of liability insurance","It is the core commercial application that captures the applicant''s identity and operations, with line-of-business sections attached","It is used only to report claims","It replaces every line-specific application"]'::jsonb, 1, 'The 125 is the master commercial application. Line sections such as the 126 (GL), 127 (Auto) and 140 (Property) are attached to it.'),
  ('125', 'gl_section', 2, 'Which ACORD form is the Commercial General Liability section that attaches to the ACORD 125?', '["ACORD 25","ACORD 126","ACORD 127","ACORD 140"]'::jsonb, 1, 'The ACORD 126 is the Commercial General Liability section.'),
  ('125', 'llc_entity', 3, 'The insured''s legal name is "Riverstone Construction Co., LLC". Which legal-entity box should be checked?', '["Corporation","Partnership","Limited Liability Company (LLC)","Individual"]'::jsonb, 2, 'The legal name ends in "LLC", so the entity type is Limited Liability Company.'),
  ('125', 'dba', 4, 'Where is a DBA (trade name) such as "Riverstone Builders" shown on the 125?', '["In the Named Insured section, together with the legal name","In the Additional Interest section","In the Prior Carrier section","It is never recorded"]'::jsonb, 0, 'The DBA belongs with the named insured, e.g. "Riverstone Construction Co., LLC DBA Riverstone Builders".'),
  ('125', 'lines_requested', 5, 'The producer asks for General Liability, Commercial Auto and Commercial Property. What should you do in the lines-of-business area of the 125?', '["Check only General Liability","Leave it blank — the underwriter decides","Check every line requested in the submission","Check every box on the form"]'::jsonb, 2, 'Indicate exactly the lines being requested so the matching ACORD sections are attached.'),
  ('125', 'addl_insured', 6, 'What is an Additional Insured?', '["Anyone who receives a certificate of insurance","A party (often a client) given coverage under the insured''s liability policy for claims arising from the insured''s work","The insured''s prior carrier","A lender that finances the building"]'::jsonb, 1, 'An additional insured is extended coverage under the policy. A certificate holder only receives proof of insurance.'),
  ('125', 'cert_holder', 7, 'What is the difference between a certificate holder and an additional insured?', '["There is no difference","A certificate holder receives proof of coverage only; an additional insured actually has coverage under the policy","A certificate holder pays part of the premium","An additional insured only receives a copy of the policy"]'::jsonb, 1, 'Being a certificate holder grants no coverage rights; being an additional insured does.'),
  ('125', 'prior_carrier', 8, 'Where do you record that the prior carrier was Travelers, expiring 01/15/2027?', '["Prior Carrier Information","Additional Interest","Premises Information","Remarks only"]'::jsonb, 0, 'Prior carrier name, policy number and dates go in the Prior Carrier Information section.'),
  ('125', 'loss_history', 9, 'How many years of loss history does the ACORD 125 ask for?', '["1 year","3 years","5 years","10 years"]'::jsonb, 2, 'The 125 Loss History section asks for losses in the prior 5 years (or since inception, if shorter).'),
  ('125', 'revenue_format', 10, 'The email says annual gross receipts are "~$4.2M". How should this be entered?', '["4.2","4.2M","4,200,000","420,000"]'::jsonb, 2, 'Amounts are entered as full dollar figures: 4,200,000.'),
  ('125', 'ops_desc', 11, 'What makes a good Description of Operations?', '["A single word such as \"Construction\"","A specific description of what the business does, including key exposures and what it does not do","The insured''s website address","The class code only"]'::jsonb, 1, 'Underwriters need specifics, e.g. "General contractor – commercial builds; light demolition, concrete, framing, finish carpentry; no residential work."'),
  ('125', 'missing_info', 12, 'The submission email does not include the insured''s FEIN. What should you do?', '["Make up a number so the form is complete","Copy the agency''s FEIN","Leave it blank and flag it to the producer as missing","Enter 00-0000000"]'::jsonb, 2, 'Never invent data on an application. Leave it blank and ask the producer for it.'),
  ('125', 'premises_addr', 13, 'Where does the location where the business actually operates go?', '["Only the mailing address","The Premises Information (location) section","The Producer section","The Additional Interest section"]'::jsonb, 1, 'Each physical location goes in Premises Information, even if it matches the mailing address.'),
  ('125', 'date_format', 14, 'What format does ACORD use for dates?', '["DD/MM/YYYY","MM/DD/YYYY","YYYY/DD/MM","Any format is fine"]'::jsonb, 1, 'ACORD forms use MM/DD/YYYY.'),
  ('125', 'ai_zip', 15, 'The insured''s ZIP is 95841 and the additional insured''s ZIP is 95814. Why must you check each one?', '["ZIP codes are not important","Each party''s address must be copied exactly — transposed digits send documents to the wrong place","The form only allows one ZIP code","The underwriter fixes ZIP codes"]'::jsonb, 1, 'Similar-looking numbers are a classic attention-to-detail error. Copy each address exactly.'),
  ('126', 'purpose', 1, 'What is the ACORD 126?', '["The Business Auto section","The Commercial General Liability section attached to the ACORD 125","The Workers Compensation application","A certificate of insurance"]'::jsonb, 1, 'The 126 details GL exposures, classifications and limits, and attaches to the 125.'),
  ('126', 'exposure_basis', 2, 'What does the "premium basis" (exposure basis) on the GL hazard schedule describe?', '["The deductible","The unit the premium is rated on — e.g. gross sales, payroll, area or units","The number of claims","The agency commission"]'::jsonb, 1, 'Each class is rated on a specific exposure basis, and the exposure amount is entered in that unit.'),
  ('126', 'code_s', 3, 'On the 126 hazard schedule, premium basis code "S" stands for:', '["Square feet","Gross sales","Subcontracted cost","Seats"]'::jsonb, 1, 'S = Gross Sales. (A = Area, P = Payroll, C = Total Cost, U = Units, M = Admissions.)'),
  ('126', 'code_p', 4, 'Premium basis code "P" stands for:', '["Payroll","Premises","Products","Policy"]'::jsonb, 0, 'P = Payroll. It is common for contractor classifications.'),
  ('126', 'restaurant_basis', 5, 'A full-service restaurant is most commonly rated on which exposure basis?', '["Area (square feet)","Gross sales","Number of vehicles","Admissions"]'::jsonb, 1, 'Restaurant GL classifications are typically rated per $1,000 of gross sales.'),
  ('126', 'each_occurrence', 6, 'What does the Each Occurrence limit mean?', '["The most the policy pays for all claims in the policy year","The most the policy pays for all damages arising from a single occurrence","The deductible per claim","The limit for medical payments only"]'::jsonb, 1, 'Each Occurrence caps what is paid for any one occurrence, regardless of how many people are injured.'),
  ('126', 'gen_agg', 7, 'What does the General Aggregate limit mean?', '["The most the policy pays for one claim","The most the policy pays during the policy period for covered claims (other than products/completed operations)","The premium for the policy","The limit for damage to rented premises"]'::jsonb, 1, 'The general aggregate is the total cap for the policy period. Products/completed operations has its own aggregate.'),
  ('126', 'limits_notation', 8, 'A request for "$1,000,000 / $2,000,000" GL limits means:', '["$1M aggregate / $2M each occurrence","$1M each occurrence / $2M general aggregate","$1M deductible / $2M limit","$1M products / $2M medical"]'::jsonb, 1, 'By convention it is each occurrence / general aggregate.'),
  ('126', 'products_co', 9, 'What does the Products–Completed Operations aggregate cover?', '["Injury or damage from products the insured sold or work it completed, after it leaves their control or the job is finished","Damage to the insured''s own building","Employee injuries","Vehicle accidents"]'::jsonb, 0, 'It is a separate aggregate for claims arising from products sold and finished work.'),
  ('126', 'occurrence_form', 10, 'An occurrence-based GL policy covers:', '["Only claims reported while the policy is active","Injury or damage that occurs during the policy period, even if the claim is made later","Only claims over the deductible","Only incidents on the insured''s premises"]'::jsonb, 1, 'Occurrence forms respond to when the injury or damage happened. Claims-made forms respond to when the claim is made.'),
  ('126', 'second_class', 11, 'The restaurant also does off-site catering worth about $45K a year. How is this shown on the 126?', '["Ignore it — it is part of the restaurant","As a separate classification line with its own exposure amount","In the Additional Interest section","As a deductible"]'::jsonb, 1, 'Each distinct operation gets its own hazard line, class code and exposure.'),
  ('126', 'pai', 12, 'Personal and Advertising Injury coverage responds to claims such as:', '["Slip-and-fall injuries","Libel, slander, false arrest or copyright infringement in advertising","Food poisoning","Theft of business property"]'::jsonb, 1, 'Personal and advertising injury covers offenses like defamation and invasion of privacy, not bodily injury.'),
  ('126', 'med_exp', 13, 'The GL Medical Expense limit pays:', '["Employees'' medical bills","Medical bills of a member of the public injured on the premises, regardless of fault, up to a small per-person limit","The insured''s own health insurance","Only bills from auto accidents"]'::jsonb, 1, 'Med pay is a no-fault, per-person limit that helps resolve minor injuries quickly.'),
  ('126', 'class_accuracy', 14, 'Why does an accurate class code and exposure amount matter on the 126?', '["It does not matter — the audit fixes everything","It drives the premium, and errors cause audit adjustments and possible coverage problems","It only affects the agency commission","It only matters for workers comp"]'::jsonb, 1, 'Class codes and exposures set the rate. Wrong entries lead to mispriced quotes and audit surprises.'),
  ('126', 'rented_premises', 15, 'Damage to Rented Premises coverage protects against:', '["Damage the insured causes to premises it rents, such as a fire it started in a leased space","Damage to the insured''s owned vehicles","Theft of inventory","Employee injury"]'::jsonb, 0, 'It covers the tenant''s liability for damage to premises rented to them.'),
  ('127', 'purpose', 1, 'What is the ACORD 127 used for?', '["Property values","The Business Auto section — drivers, vehicles and auto coverages","Workers compensation payroll","General liability class codes"]'::jsonb, 1, 'The 127 schedules drivers and vehicles for a commercial auto submission.'),
  ('127', 'symbol_1', 2, 'Business auto coverage Symbol 1 means:', '["Owned autos only","Any auto","Hired autos only","Specifically described autos"]'::jsonb, 1, 'Symbol 1 = Any Auto, the broadest liability symbol.'),
  ('127', 'symbol_7', 3, 'Which symbol covers only the vehicles specifically listed (scheduled) on the policy?', '["Symbol 1","Symbol 2","Symbol 7","Symbol 9"]'::jsonb, 2, 'Symbol 7 = Specifically Described Autos. Symbol 2 = Owned Autos Only.'),
  ('127', 'symbol_8_9', 4, 'Symbols 8 and 9 refer to:', '["Hired autos (8) and non-owned autos (9)","Owned private passenger autos (8) and trucks (9)","Trailers (8) and mobile equipment (9)","Collision (8) and comprehensive (9)"]'::jsonb, 0, '8 = Hired Autos Only, 9 = Non-Owned Autos Only. Together they provide "hired and non-owned" coverage.'),
  ('127', 'hno', 5, 'Hired & Non-Owned Auto liability protects the business when:', '["A company truck is stolen","An employee drives a rental car or their own car on company business and causes an accident","A customer''s car is damaged in the insured''s parking lot","A vehicle needs towing"]'::jsonb, 1, 'It covers the company''s liability for autos it does not own: rented or hired vehicles and employees'' personal vehicles.'),
  ('127', 'csl', 6, '"$1,000,000 CSL" means:', '["$1M for bodily injury only","One combined single limit of $1M per accident for bodily injury and property damage together","$1M collision deductible","$1M per vehicle per year"]'::jsonb, 1, 'A combined single limit applies one limit to BI and PD combined per accident.'),
  ('127', 'vin', 7, 'How many characters are in a modern (1981 and newer) VIN?', '["10","12","17","20"]'::jsonb, 2, 'Modern VINs are 17 characters and must be copied exactly.'),
  ('127', 'cost_new', 8, '"Cost New" for a vehicle means:', '["Today''s market value","The original cost of the vehicle when new, including permanently attached equipment","The loan balance","The annual premium"]'::jsonb, 1, 'Cost new is the original purchase price when new. It is used for rating physical damage.'),
  ('127', 'garaging', 9, 'Why is the garaging ZIP code of each vehicle important?', '["It is where the title is mailed","It determines the rating territory","It is optional","It is only used for trailers"]'::jsonb, 1, 'Rates vary by territory, which is based on where the vehicle is principally garaged.'),
  ('127', 'radius', 10, 'What does "radius of operation" (e.g. 500 miles) describe?', '["The vehicle''s fuel range","How far from its garaging location the vehicle typically travels — a key rating factor","The turning radius of the truck","The distance to the agency"]'::jsonb, 1, 'Longer radius (long-haul) operations carry more exposure and are rated higher.'),
  ('127', 'comprehensive', 11, 'Comprehensive (other-than-collision) coverage pays for:', '["Damage from hitting another vehicle","Losses such as theft, fire, hail, vandalism and glass breakage","Injuries to other drivers","Medical bills of passengers"]'::jsonb, 1, 'Comprehensive covers physical damage from causes other than collision or overturn.'),
  ('127', 'collision', 12, 'Collision coverage pays for:', '["Damage to the insured vehicle from colliding with another object or overturning","Theft of the vehicle","Liability to others","Rental reimbursement only"]'::jsonb, 0, 'Collision covers damage to the insured''s own vehicle from a collision or upset.'),
  ('127', 'um', 13, 'Uninsured/Underinsured Motorist coverage protects against:', '["Damage the insured causes to others","Injuries caused by an at-fault driver who has no insurance or too little insurance","Vehicles not listed on the policy","Drivers without a license"]'::jsonb, 1, 'UM/UIM pays the insured''s injuries when the at-fault driver cannot pay.'),
  ('127', 'driver_fields', 14, 'Which details are needed for each driver on the 127?', '["Name only","Name, date of birth, driver''s license number and license state","Phone number and e-mail","Social media handle"]'::jsonb, 1, 'Underwriters use the license number and state to pull each driver''s motor vehicle record (MVR).'),
  ('127', 'schedule', 15, 'The fleet has 8 vehicles but the form only has room for 4. What should you do?', '["List the 4 most expensive vehicles only","List 4 and check that an additional vehicle schedule is attached for the rest","Combine two vehicles per row","Leave the vehicle section blank"]'::jsonb, 1, 'Every unit must be scheduled. Use an attached schedule and indicate it on the form.'),
  ('130', 'purpose', 1, 'What is the ACORD 130?', '["A property application","The Workers Compensation application — employer details, class codes, payroll and owners/officers","A business auto schedule","A certificate of insurance"]'::jsonb, 1, 'The 130 captures everything needed to rate and underwrite workers compensation.'),
  ('130', 'class_code', 2, 'What is an NCCI class code used for?', '["To identify the insurance carrier","To classify employees by the type of work they do, which determines the rate","To identify the policy number","To track claims"]'::jsonb, 1, 'Each class code has its own rate based on the hazard of that work.'),
  ('130', 'rate_basis', 3, 'Workers comp premium is typically calculated as:', '["Number of employees × rate","(Payroll ÷ 100) × rate for each class code","Revenue × rate","A flat fee per state"]'::jsonb, 1, 'WC rates are applied per $100 of payroll in each class.'),
  ('130', 'clerical', 4, 'Class code 8810 is used for:', '["Roofing","Clerical office employees","Outside sales","Truck drivers"]'::jsonb, 1, '8810 = Clerical Office Employees, one of the lowest-rated classes.'),
  ('130', 'separate_payroll', 5, 'Why must payroll be split by class code instead of entered as one total?', '["To make the form longer","Each class has a different rate, so lumping payroll together misprices the policy and causes audit adjustments","It is optional","Only the highest class matters"]'::jsonb, 1, 'Payroll must follow the class it belongs to: roofers in the roofing class, office staff in 8810, and so on.'),
  ('130', 'part_one', 6, 'Part One of a workers compensation policy provides:', '["Employer''s liability","Statutory workers compensation benefits required by state law","Other states coverage","General liability"]'::jsonb, 1, 'Part One pays the benefits each state''s workers comp law requires.'),
  ('130', 'part_two', 7, 'Part Two of a workers compensation policy is:', '["Employer''s Liability","Other States Insurance","Medical payments","Umbrella coverage"]'::jsonb, 0, 'Part Two (Employer''s Liability) covers lawsuits arising from employee injuries outside the statutory benefits.'),
  ('130', 'el_limits', 8, 'Employer''s liability limits of "$1,000,000 / $1,000,000 / $1,000,000" represent:', '["Three separate policies","Each Accident / Disease – Policy Limit / Disease – Each Employee","Bodily injury / property damage / medical","Three years of coverage"]'::jsonb, 1, 'Employer''s liability has three limits: each accident, disease policy limit and disease each employee.'),
  ('130', 'part_three', 9, 'Part Three (Other States Insurance) is needed when:', '["The employer has more than 50 employees","Employees may work in states other than those listed in Part One","The employer is an LLC","The policy has a deductible"]'::jsonb, 1, 'Listing other states (e.g. UT, WY, NM, AZ) extends coverage if work occurs there.'),
  ('130', 'officers', 10, 'Why do you record each owner/officer''s ownership % and include/exclude status?', '["For marketing purposes","Included officers are covered and their payroll is rated; excluded officers are not covered — this must match what the insured elected","It is only needed for corporations over 100 employees","To calculate the agency commission"]'::jsonb, 1, 'Owner/officer elections affect both coverage and premium, and states have rules on who may be excluded.'),
  ('130', 'fein', 11, 'What is the correct format of a FEIN?', '["9 digits, written XX-XXXXXXX","10 digits, written XXX-XXX-XXXX","The same as a Social Security number","Letters and numbers"]'::jsonb, 0, 'A Federal Employer Identification Number has 9 digits, e.g. 84-3920174.'),
  ('130', 'emr', 12, 'An experience modification factor (mod) of 1.25 means:', '["The employer''s losses are better than average and premium is reduced","The employer''s losses are worse than average and premium is increased about 25%","The policy has a 25% deductible","The employer has 125 employees"]'::jsonb, 1, 'A mod above 1.00 increases premium, and a mod below 1.00 decreases it.'),
  ('130', 'payroll_estimate', 13, 'The payroll entered on the 130 is:', '["Last year''s exact payroll, which can never change","The estimated annual payroll for the upcoming policy period, verified later by audit","The owner''s salary only","Optional"]'::jsonb, 1, 'Premium is based on estimated payroll and adjusted to actual payroll at the year-end audit.'),
  ('130', 'claims', 14, 'The insured had a lost-time claim of about $28K in 2024. What should you do?', '["Leave it off to get a better quote","Disclose it in the loss history / prior carrier information","Mention it only if the underwriter asks","Report it as a GL claim"]'::jsonb, 1, 'All losses must be disclosed accurately. Omitting them is misrepresentation.'),
  ('130', 'roofing_class', 15, 'Roofing employees and solar-installation (electrical) employees at the same company should be:', '["Put under one class code","Assigned to their own appropriate class codes, each with its own payroll and employee count","Excluded from coverage","Classified as clerical"]'::jsonb, 1, 'Each distinct type of work gets its own class code. In the scenario that is 5551 roofing, 5190 electrical/solar, 8810 clerical and 7380 sales/outside.'),
  ('140', 'purpose', 1, 'What is the ACORD 140?', '["The Property section — building and contents values, construction, protection and coverage details","The General Liability section","An auto ID card","A workers comp application"]'::jsonb, 0, 'The 140 captures the insurance-to-value and building information needed to rate property.'),
  ('140', 'jm', 2, 'In the ISO construction classes, "Joisted Masonry" is class:', '["1","2","4","6"]'::jsonb, 1, '1 Frame, 2 Joisted Masonry, 3 Non-Combustible, 4 Masonry Non-Combustible, 5 Modified Fire Resistive, 6 Fire Resistive.'),
  ('140', 'frame', 3, 'Which construction class is generally the most susceptible to fire?', '["Fire Resistive (6)","Masonry Non-Combustible (4)","Frame (1)","Non-Combustible (3)"]'::jsonb, 2, 'Frame (wood) construction is the most combustible and the highest rated.'),
  ('140', 'protection_class', 4, 'Fire protection classes range from 1 to 10. Which is best?', '["1","5","10","They are all equal"]'::jsonb, 0, 'Class 1 has the best fire protection, and class 10 is essentially unprotected.'),
  ('140', 'special_form', 5, 'Which causes-of-loss form gives the broadest coverage?', '["Basic","Broad","Special","Named perils"]'::jsonb, 2, 'The Special form covers all direct physical loss except what is specifically excluded.'),
  ('140', 'coinsurance', 6, 'An 80% coinsurance clause requires the insured to:', '["Pay 80% of every loss","Carry a limit of at least 80% of the property''s value, or face a penalty at claim time","Insure only 80% of the building","Pay an 80% deductible"]'::jsonb, 1, 'Underinsuring below the coinsurance percentage reduces the claim payment proportionally.'),
  ('140', 'coins_math', 7, 'Building value $1,000,000, 80% coinsurance, limit carried $600,000, loss $100,000. Ignoring the deductible, what does the insurer pay?', '["$100,000","$80,000","$75,000","$60,000"]'::jsonb, 2, 'Required = $800,000. Paid = ($600,000 ÷ $800,000) × $100,000 = $75,000.'),
  ('140', 'rc_acv', 8, 'Replacement Cost valuation differs from Actual Cash Value because Replacement Cost:', '["Deducts depreciation","Pays to repair or replace with like kind and quality without deducting depreciation","Pays market value of the land","Is always cheaper"]'::jsonb, 1, 'ACV = replacement cost minus depreciation. RC pays the full cost to replace.'),
  ('140', 'bpp', 9, 'Business Personal Property (BPP) includes:', '["The building itself","Machinery, equipment, furniture, inventory and stock owned by the business","Company vehicles","Employees'' personal cars"]'::jsonb, 1, 'BPP covers the contents and stock, separately from the building.'),
  ('140', 'bi', 10, 'Business Income coverage pays for:', '["Physical damage to the building","Lost net income and continuing expenses while operations are suspended by a covered loss","Employee wages for overtime only","Inventory theft"]'::jsonb, 1, 'Business income is a "time element" coverage for the income lost while the business is shut down.'),
  ('140', 'sprinkler', 11, 'A building is "fully sprinklered throughout". What sprinkler percentage should be entered?', '["0%","50%","80%","100%"]'::jsonb, 3, 'Fully sprinklered means 100% of the area is protected, which earns better rates.'),
  ('140', 'updates', 12, 'Why does the 140 ask for the year wiring, roofing, plumbing and heating were updated?', '["For the building permit","Updated systems reduce the risk of fire and water losses, so underwriters rate them","It is decorative information","Only for buildings built after 2010"]'::jsonb, 1, 'Recent updates (e.g. wiring 2020, roof 2021) show the building is in good condition.'),
  ('140', 'ordinance', 13, 'Ordinance or Law coverage pays for:', '["Fines for building code violations","Extra costs to rebuild to current building codes, including demolishing undamaged parts","Legal defense in lawsuits","Zoning permit fees for new buildings"]'::jsonb, 1, 'Standard forms exclude code-upgrade costs. Ordinance or Law coverage adds them back.'),
  ('140', 'earthquake', 14, 'Under a standard Special causes-of-loss form, earthquake is generally:', '["Covered automatically","Excluded unless added by endorsement or separate policy","Covered only for frame buildings","Covered up to the coinsurance amount"]'::jsonb, 1, 'Earth movement is excluded and must be bought separately if wanted.'),
  ('140', 'sewer', 15, 'Water that backs up through sewers or drains is:', '["Always covered by the Special form","Typically excluded unless backup of sewer/drain coverage is added","Covered only by flood insurance","Covered under business income"]'::jsonb, 1, 'Sewer/drain backup is a common exclusion, so it is added by endorsement when requested.')
ON CONFLICT (module_id, question_key) DO UPDATE SET
  sort_order = EXCLUDED.sort_order, prompt = EXCLUDED.prompt, options = EXCLUDED.options,
  correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, is_active = true, updated_at = now();

-- Questions removed from questions.mjs are retired (kept for attempt history).
UPDATE public.knowledge_check_questions SET is_active = false, updated_at = now()
WHERE (module_id, question_key) NOT IN (('125', 'purpose'), ('125', 'gl_section'), ('125', 'llc_entity'), ('125', 'dba'), ('125', 'lines_requested'), ('125', 'addl_insured'), ('125', 'cert_holder'), ('125', 'prior_carrier'), ('125', 'loss_history'), ('125', 'revenue_format'), ('125', 'ops_desc'), ('125', 'missing_info'), ('125', 'premises_addr'), ('125', 'date_format'), ('125', 'ai_zip'), ('126', 'purpose'), ('126', 'exposure_basis'), ('126', 'code_s'), ('126', 'code_p'), ('126', 'restaurant_basis'), ('126', 'each_occurrence'), ('126', 'gen_agg'), ('126', 'limits_notation'), ('126', 'products_co'), ('126', 'occurrence_form'), ('126', 'second_class'), ('126', 'pai'), ('126', 'med_exp'), ('126', 'class_accuracy'), ('126', 'rented_premises'), ('127', 'purpose'), ('127', 'symbol_1'), ('127', 'symbol_7'), ('127', 'symbol_8_9'), ('127', 'hno'), ('127', 'csl'), ('127', 'vin'), ('127', 'cost_new'), ('127', 'garaging'), ('127', 'radius'), ('127', 'comprehensive'), ('127', 'collision'), ('127', 'um'), ('127', 'driver_fields'), ('127', 'schedule'), ('130', 'purpose'), ('130', 'class_code'), ('130', 'rate_basis'), ('130', 'clerical'), ('130', 'separate_payroll'), ('130', 'part_one'), ('130', 'part_two'), ('130', 'el_limits'), ('130', 'part_three'), ('130', 'officers'), ('130', 'fein'), ('130', 'emr'), ('130', 'payroll_estimate'), ('130', 'claims'), ('130', 'roofing_class'), ('140', 'purpose'), ('140', 'jm'), ('140', 'frame'), ('140', 'protection_class'), ('140', 'special_form'), ('140', 'coinsurance'), ('140', 'coins_math'), ('140', 'rc_acv'), ('140', 'bpp'), ('140', 'bi'), ('140', 'sprinkler'), ('140', 'updates'), ('140', 'ordinance'), ('140', 'earthquake'), ('140', 'sewer'));

-- ============================================================ helpers
CREATE OR REPLACE FUNCTION lava_private.module_videos_complete(p_uid uuid, p_module_id text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM public.training_materials WHERE module_id = p_module_id AND material_type = 'video' AND is_current)
     AND NOT EXISTS (
       SELECT 1 FROM public.training_materials t
       LEFT JOIN public.video_progress vp ON vp.asset_key = t.asset_key AND vp.user_id = p_uid
       WHERE t.module_id = p_module_id AND t.material_type = 'video' AND t.is_current AND t.is_required
         AND coalesce(vp.completed, false) = false)
$$;
REVOKE EXECUTE ON FUNCTION lava_private.module_videos_complete(uuid, text) FROM PUBLIC, anon, authenticated;

-- ============================================================ student RPCs
-- Status + questions (without answers). Questions are only returned once the video is complete and the check is not yet passed.
CREATE OR REPLACE FUNCTION public.get_knowledge_check(p_module_id text) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_count integer;
  v_video boolean;
  v_passed boolean;
  v_best integer;
  v_attempts integer;
  v_last jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED'; END IF;
  SELECT count(*) INTO v_count FROM public.knowledge_check_questions WHERE module_id = p_module_id AND is_active;
  v_video := lava_private.module_videos_complete(v_uid, p_module_id);
  SELECT coalesce(bool_or(passed), false), max(score), count(*) INTO v_passed, v_best, v_attempts
    FROM public.knowledge_check_attempts WHERE user_id = v_uid AND module_id = p_module_id;
  SELECT jsonb_build_object('score', score, 'correct', correct, 'total', total, 'passed', passed, 'created_at', created_at,
           'results', CASE WHEN passed THEN results ELSE '[]'::jsonb END)
    INTO v_last FROM public.knowledge_check_attempts
    WHERE user_id = v_uid AND module_id = p_module_id ORDER BY passed DESC, created_at DESC LIMIT 1;

  RETURN jsonb_build_object(
    'question_count', v_count,
    'pass_score', 80,
    'video_complete', v_video,
    'passed', v_passed,
    'best_score', v_best,
    'attempts', v_attempts,
    'last_attempt', v_last,
    'questions', CASE WHEN v_video AND NOT v_passed AND v_count > 0 THEN (
      SELECT jsonb_agg(jsonb_build_object('id', id, 'prompt', prompt, 'options', options) ORDER BY sort_order)
      FROM public.knowledge_check_questions WHERE module_id = p_module_id AND is_active) ELSE '[]'::jsonb END);
END $$;

-- p_answers: { "<question id>": <chosen option index>, ... }
CREATE OR REPLACE FUNCTION public.submit_knowledge_check(p_module_id text, p_answers jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_uid uuid := auth.uid();
  qrow record;
  v_given integer;
  v_ok boolean;
  v_correct integer := 0;
  v_total integer := 0;
  v_score integer;
  v_passed boolean;
  v_results jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED'; END IF;
  IF p_answers IS NULL OR jsonb_typeof(p_answers) <> 'object' THEN RAISE EXCEPTION 'INVALID_VALUES'; END IF;
  IF NOT lava_private.module_videos_complete(v_uid, p_module_id) THEN RAISE EXCEPTION 'VIDEO_INCOMPLETE'; END IF;
  IF EXISTS (SELECT 1 FROM public.knowledge_check_attempts WHERE user_id = v_uid AND module_id = p_module_id AND passed) THEN
    RAISE EXCEPTION 'KNOWLEDGE_CHECK_ALREADY_PASSED';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('kc:' || v_uid::text || ':' || p_module_id));

  FOR qrow IN SELECT * FROM public.knowledge_check_questions WHERE module_id = p_module_id AND is_active ORDER BY sort_order LOOP
    v_total := v_total + 1;
    v_given := CASE WHEN jsonb_typeof(p_answers -> qrow.id::text) = 'number' THEN (p_answers ->> qrow.id::text)::integer END;
    v_ok := v_given IS NOT NULL AND v_given = qrow.correct_index;
    IF v_ok THEN v_correct := v_correct + 1; END IF;
    v_results := v_results || jsonb_build_array(jsonb_build_object(
      'id', qrow.id, 'prompt', qrow.prompt, 'options', qrow.options, 'given', v_given, 'correct', v_ok,
      'correct_index', qrow.correct_index, 'explanation', qrow.explanation));
  END LOOP;
  IF v_total = 0 THEN RAISE EXCEPTION 'KNOWLEDGE_CHECK_NOT_FOUND'; END IF;

  v_score := round(v_correct * 100.0 / v_total);
  v_passed := v_score >= 80;
  INSERT INTO public.knowledge_check_attempts (user_id, module_id, score, correct, total, passed, answers, results)
  VALUES (v_uid, p_module_id, v_score, v_correct, v_total, v_passed, p_answers, v_results);

  RETURN jsonb_build_object('score', v_score, 'correct', v_correct, 'total', v_total, 'passed', v_passed, 'pass_score', 80,
    -- Before passing, only reveal which questions were wrong — not the right answers.
    'results', CASE WHEN v_passed THEN v_results ELSE (
      SELECT coalesce(jsonb_agg(jsonb_build_object('id', r->'id', 'prompt', r->'prompt', 'given', r->'given', 'correct', r->'correct')), '[]'::jsonb)
      FROM jsonb_array_elements(v_results) r) END);
END $$;

-- Staff: let a student retake a passed check (e.g. after the video or questions change).
CREATE OR REPLACE FUNCTION public.staff_reset_knowledge_check(p_user_id uuid, p_module_id text) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE n integer;
BEGIN
  IF NOT public.is_staff() THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  DELETE FROM public.knowledge_check_attempts WHERE user_id = p_user_id AND module_id = p_module_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;

-- ============================================================ assessment gate
CREATE OR REPLACE FUNCTION public.start_assessment(p_module_id text) RETURNS public.assessment_attempts
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_pdf public.training_materials;
  v_attempt public.assessment_attempts;
  v_used integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.acord_modules WHERE id = p_module_id) THEN RAISE EXCEPTION 'MODULE_NOT_FOUND'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext(v_uid::text || ':' || p_module_id));

  -- Resume an attempt already in progress.
  SELECT * INTO v_attempt FROM public.assessment_attempts
    WHERE user_id = v_uid AND module_id = p_module_id AND status = 'in_progress';
  IF v_attempt.id IS NOT NULL THEN RETURN v_attempt; END IF;

  -- Video gate: at least one current video, and every required current video completed.
  IF NOT EXISTS (SELECT 1 FROM public.training_materials WHERE module_id = p_module_id AND material_type = 'video' AND is_current) THEN
    RAISE EXCEPTION 'NO_VIDEO';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.training_materials t
    LEFT JOIN public.video_progress vp ON vp.asset_key = t.asset_key AND vp.user_id = v_uid
    WHERE t.module_id = p_module_id AND t.material_type = 'video' AND t.is_current AND t.is_required
      AND coalesce(vp.completed, false) = false) THEN
    RAISE EXCEPTION 'VIDEO_INCOMPLETE';
  END IF;

  -- Knowledge Check gate: the module's quiz must be passed before the PDF assessment.
  IF EXISTS (SELECT 1 FROM public.knowledge_check_questions WHERE module_id = p_module_id AND is_active)
     AND NOT EXISTS (SELECT 1 FROM public.knowledge_check_attempts WHERE user_id = v_uid AND module_id = p_module_id AND passed) THEN
    RAISE EXCEPTION 'KNOWLEDGE_CHECK_NOT_PASSED';
  END IF;

  SELECT * INTO v_pdf FROM public.training_materials WHERE module_id = p_module_id AND material_type = 'pdf' AND is_current;
  IF v_pdf.id IS NULL THEN RAISE EXCEPTION 'NO_PDF'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.pdf_form_fields WHERE material_id = v_pdf.id AND field_type NOT IN ('button', 'signature')) THEN
    RAISE EXCEPTION 'PDF_NOT_FILLABLE';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.pdf_field_mappings WHERE material_id = v_pdf.id AND is_scored AND points > 0
                   AND (coalesce(expected_value, '') <> '' OR match_type = 'present' OR missing_rule = 'expect_blank')) THEN
    RAISE EXCEPTION 'GRADING_NOT_CONFIGURED';
  END IF;

  SELECT count(*) INTO v_used FROM public.assessment_attempts WHERE user_id = v_uid AND module_id = p_module_id AND status = 'submitted';
  IF v_used >= 3 THEN RAISE EXCEPTION 'NO_ATTEMPTS_REMAINING'; END IF;

  INSERT INTO public.assessment_attempts (user_id, module_id, material_id, student_name, attempt_number, status, started_at,
      score, correct, incorrect, missing, total_fields, completion_time_min, field_values, field_results, completed_at)
  VALUES (v_uid, p_module_id, v_pdf.id, coalesce((SELECT NULLIF(full_name, '') FROM public.profiles WHERE id = v_uid), 'Trainee'),
      v_used + 1, 'in_progress', now(), 0, 0, 0, 0, 0, 0, '{}'::jsonb, '[]'::jsonb, NULL)
  RETURNING * INTO v_attempt;
  RETURN v_attempt;
END $$;

REVOKE EXECUTE ON FUNCTION public.get_knowledge_check(text), public.submit_knowledge_check(text, jsonb),
  public.staff_reset_knowledge_check(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_knowledge_check(text), public.submit_knowledge_check(text, jsonb),
  public.staff_reset_knowledge_check(uuid, text), public.start_assessment(text) TO authenticated;
